var FG = "#000000";
// === Tab: Terminal ===
class Terminal {
	constructor(x, y, sze, w, h) {
		this.pos = {x, y};
		this.sze = sze;
		this.dim = {w, h};
		this.cur = {x: 0, y: 0};

		// generate and store one empty line (for new line)
		let emptyLine = "";
		for (i = 0; i < w; i++) emptyLine += " ";
		this.emptyLine = emptyLine;

		// store #h of empty lines
		this.content = Array(h);
		for (i = 0; i < h; i++) {
			this.content[i] = emptyLine;
		}
	} 

	// insert new line
	newLine() {
		this.cur.x = 0;
		this.cur.y++;
		if (this.cur.y >= this.dim.h) {
			this.content.shift();
			this.content.push(this.emptyLine);
			this.cur.y = this.dim.h - 1;
		}
	} // newLine

	// insert specific char, eval "\n"
	insertChar(ch) {
		if (ch === "\n") return this.newLine();

		function replaceCharAt(str,index,chr) { // sub function
    	if (index > str.length-1) return str;
    	return str.substring(0,index) + chr + str.substring(index+1);
		}

		this.content[this.cur.y] = replaceCharAt(this.content[this.cur.y], this.cur.x, ch);
		this.cur.x++;

		if (this.cur.x >= this.dim.w) {
			this.newLine();
		}
	} // insertChar

	// insert string
	insert(msg) {
		for (i = 0; i < msg.length; i++) this.insertChar(msg[i]);
	} // insert

	// display terminal (with blinking cursor)
	show() {
		push();
		textSize(this.sze);
		textAlign(LEFT, TOP);
		translate(this.pos.x, this.pos.y);
		for (i = 0; i < this.dim.h; i++) {		
			text(this.content[i], 0, i*this.sze)
		}

		// blink frequency (somehow 3 / second)
		const bfr = fract(millis()/650);
		if (bfr < 0.5) {
			rect(this.cur.x * this.sze, this.cur.y * this.sze, this.sze);
		}
		pop();
	} // show

} // class Terminal

