var S, PAD = 3;
var pixelFont;
var trml;
var crtShader; // from tarot #wccchallenge https://openprocessing.org/sketch/2373263 

function preload() {
	// https://developers.google.com/fonts/docs/getting_started?hl=de&apix_params=%7B%22family%22%3A%5B%22Press%20Start%202P%22%5D%7D
  pixelFont = loadFont("https://fonts.gstatic.com/s/pressstart2p/v15/e3t4euO8T-267oIAQAu6jDQyK0nSgPJE4580.ttf");
}

var autoInput = ("10 PRINT CHR$(205.5+RND(1)); : GOTO 10\nRUN\n").split('');

// https://www.c64-wiki.de/images/2/2c/c64_16farben.png
var CLRS = [
	"#000000","#ffffff","#8d4940","#8cc5cc",
	"#9254b3","#76b052","#4d3fa7","#d4de82",
	"#956831","#64510b","#bc8078","#606060",
	"#8a8a8a","#b6eb96","#897ddb","#b3b3b3"
];

var BG = CLRS[6], FG = CLRS[14];

function setup() {
	// screen is 40 * 25 characters with 3 char-width/-height border
	S = ~~min(windowWidth/(40+2*PAD), windowHeight/(25+2*PAD));
  createCanvas((40+2*PAD)*S, (25+2*PAD)*S);
	x = PAD*S;
	y = 300 - S;
  // pixelDensity(1);
  describe("10 print animation in C=64 style colors and border");
	crtShader = createFilterShader(crtShaderSrc);
  frameRate(30);
  noStroke();

	textFont(pixelFont);
	textSize(S);
	textAlign(LEFT, TOP);

	trml = new Terminal(PAD*S, PAD*S, S, 40, 25);
	// splash screen
	trml.insert(
		"\n" +
		"    **** COMMODORE 64 BASIC V2 ****\n" +
		"\n" +
		" 64K RAM SYSTEM  38911 BASIC BYTES FREE\n" +
		"\n" +
		"READY.\n"
	);

  background(CLRS[0]);
	noStroke();
}

function draw() {
	background(CLRS[0]);
	// draw inner frame
	fill(FG);
	rect(0, 0, width, height);
	fill(BG);
	rect(PAD*S, PAD*S, width-2*(PAD*S), height-2*(PAD*S));
	fill(FG);
	trml.show();

	// insert basic code
	if (autoInput.length > 0) {
		if (random() < 0.25) {
			trml.insert(autoInput.shift());
		}
	} else {	
		// "execute" basic script
		trml.insert(random() < 0.5 ? "/" : "\\");
	}

	if (!((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) filter(crtShader);
}

function keyPressed() {
	trml.insert(key)
}
